function UIActionSPMapDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local rendererFeature = KTool.GetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR)
        if rendererFeature then
            rendererFeature.settings.blurPasses = 5
            rendererFeature.settings.maskScale = CS.UnityEngine.Vector2(1, 1.46)
            rendererFeature.settings.useMask = true
        end
        KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, true)

        self._co = cs_coroutine.start(function()
            CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIActionSPMapDialogGo")

            local id = checkNumber(KCookie.Get("UIActionSPMapDialogLastGo"))
            if id > 0 then
                CfUtils.SetActive(self.Root, false)
                local fPos = self._mapCam.transform.position
                local targetGo = self._mapGo.transform:Find("CameraEndPos_"..self._regionId)
                local tPos = targetGo.transform.position
            
                local urpBase = self._mapCam:GetComponent(typeof(URPBaseCamera))
                CfUtils.DoTween(0.4, function(updateValue)
                    self._mapCam.transform.position = CS.UnityEngine.Vector3.Lerp(fPos, tPos, updateValue)
                    urpBase:CopyCamera() 
                end, function()

                end)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.4))
                CfUtils.SetActive(self.Root, true)
            end

            CfUtils.SetUICameraProjection(false, 26)
            if checkNumber(KCookie.Get("UIActionSPMapDialogEntry")) == 1 then
                CfUtils.PlayAnimator(self.controller.gameObject.transform:Find("Root"), "Entry")
            else
                CfUtils.PlayAnimator(self.controller.gameObject.transform:Find("Root"), "Loop")
            end
            KCookie.Set("UIActionSPMapDialogEntry", 0)

            CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIActionSPMapDialogGo")
        end)
    end))
    return coWait
end

