function UIActionSPMapDialog:InitData()
    local vo = ActionUtils.GetRegionSecondaryMapVo(self._regionId)
    self._mapId = vo.regionBelong

    local t = CfUtils.GetCf(AutoIds.IdSetting3040, "RegionDailyTypeVo", true)
    self._allType = checkTable(t)
end

function UIActionSPMapDialog:FillSelf()
    local vo = ActionUtils.GetRegionPrimaryMapVo(self._mapId)
    if vo then
        CfUtils.FillText(self.TxtName, localize("无回者联盟"))
    end

    self:FillTypes()
end

function UIActionSPMapDialog:FillTypes()
    for i = 1, table.count(self._allType) do
        local data = self._allType[i]
        local go = self["SpCell"..data.tab]
        self:FillTypeInfo(go, data)
    end
end

function UIActionSPMapDialog:FillTypeInfo(go, data)
    if not go or not data then
        return
    end

    local scr = CfUtils.GetLuaScr(go, "Game.UI.FightReady.UIMainChapter.UIActionSPMapDialog.UIActionSPMapNode")
    if scr then
        scr:Refresh(data)
    end
    SetButtonAction(go, Bind(self, self.OnBtnGo, data))
end

function UIActionSPMapDialog:OnBtnGo(data)
    CfUtils.SetActive(self.Root, false)
    local fPos = self._mapCam.transform.position
    local targetGo = self._mapGo.transform:Find("CameraEndPos_"..self._regionId.."_1")
    local tPos = targetGo.transform.position

    KCookie.Set("UIActionSPMapDialogLastGo", data.id)
    CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("UIActionSPMapDialogGo")
    local urpBase = self._mapCam:GetComponent(typeof(URPBaseCamera))
    CfUtils.DoTween(0.4, function(updateValue)
        self._mapCam.transform.position = CS.UnityEngine.Vector3.Lerp(fPos, tPos, updateValue)
        urpBase:CopyCamera() 
    end, function()
        print(self._mapId)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionPointMapDialog, parameters = {id = self._regionId, dailyType = data.id}}, {
            {id = Constants.UITypeIds.UIActionSPMapDialog }
        })
        CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("UIActionSPMapDialogGo")
    end)
end

function UIActionSPMapDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        -- UIModule.RemoveDialogRecord(Constants.UITypeIds.UIActionDungoenCollectionDialog)

        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._regionId = checkNumber(argument.id)  
        self._isFromEntry = checkBool(argument.isFromEntry)

        local vo = ActionUtils.GetRegionSecondaryMapVo(self._regionId)
        self._mapGo = RegionQuestMgr:GetInstance():GetCurMapGo(vo.regionBelong)
        self._mapCam = self._mapGo.transform:Find("AreaMap_01_01_Camera").gameObject:GetComponent(typeof(Camera))

        local isFinish = false
        dailyQuestComponent:DailyQuestHomeReq(function()
            isFinish = true
            self:InitData()
            self:FillSelf()
        end)
        while not isFinish do
            coroutine.yield()
        end
    end))
    return coWait
end

